const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, PageBreak,
  TableOfContents, Table, TableRow, TableCell, WidthType, BorderStyle, ShadingType,
  LevelFormat, PageNumber, Footer, TabStopType, ImageRun,
} = require('docx');

// ---------- helpers ----------
const HEB = { ascii: 'Times New Roman', hAnsi: 'Times New Roman', cs: 'David', eastAsia: 'David' };
const LINE = 360; // 1.5 spacing

function run(text, opts = {}) {
  return new TextRun({ text, font: HEB, size: 24, rightToLeft: true, ...opts });
}
// Hebrew body paragraph, justified, RTL
function P(text, opts = {}) {
  const runs = Array.isArray(text) ? text : [run(text)];
  return new Paragraph({
    bidirectional: true,
    alignment: AlignmentType.JUSTIFIED,
    spacing: { line: LINE, after: 120 },
    children: runs,
    ...opts,
  });
}
function Pind(text) { // first-line indented body paragraph
  return P(text, { indent: { firstLine: 709 } });
}
function H1(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1, bidirectional: true, alignment: AlignmentType.RIGHT,
    spacing: { before: 240, after: 240, line: LINE },
    children: [new TextRun({ text, font: HEB, size: 32, bold: true, rightToLeft: true, color: '000000' })],
  });
}
function H2(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2, bidirectional: true, alignment: AlignmentType.RIGHT,
    spacing: { before: 240, after: 120, line: LINE },
    children: [new TextRun({ text, font: HEB, size: 28, bold: true, rightToLeft: true, color: '000000' })],
  });
}
function H3(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_3, bidirectional: true, alignment: AlignmentType.RIGHT,
    spacing: { before: 200, after: 100, line: LINE },
    children: [new TextRun({ text, font: HEB, size: 24, bold: true, rightToLeft: true, color: '000000' })],
  });
}
function BR() { return new Paragraph({ children: [new PageBreak()] }); }
function EMPTY() { return new Paragraph({ children: [run('')] }); }
function BUL(text) {
  return new Paragraph({
    bidirectional: true, alignment: AlignmentType.JUSTIFIED,
    numbering: { reference: 'bul', level: 0 },
    spacing: { line: LINE, after: 60 },
    children: [run(text)],
  });
}
function NUM(text, ref) {
  return new Paragraph({
    bidirectional: true, alignment: AlignmentType.JUSTIFIED,
    numbering: { reference: ref, level: 0 },
    spacing: { line: LINE, after: 60 },
    children: [run(text)],
  });
}
// reference entries
function REF_HE(text) { // **segment** = bold (Hebrew: journal/book title in bold per APA 7 Hebrew adaptation)
  const runs = text.split('**').map((seg, i) => run(seg, i % 2 ? { bold: true } : {})).filter(r => r);
  return new Paragraph({
    bidirectional: true, alignment: AlignmentType.RIGHT,
    indent: { start: 709, hanging: 709 },
    spacing: { line: LINE, after: 120 },
    children: runs,
  });
}
function REF_EN(parts) { // parts: array of {t, i?}
  const runs = parts.map(p => new TextRun({ text: p.t, italics: !!p.i, font: { ascii: 'Times New Roman', hAnsi: 'Times New Roman', cs: 'Times New Roman' }, size: 24 }));
  return new Paragraph({
    bidirectional: false, alignment: AlignmentType.LEFT,
    indent: { left: 709, hanging: 709 },
    spacing: { line: LINE, after: 120 },
    children: runs,
  });
}
function center(text, size = 24, bold = false) {
  return new Paragraph({
    bidirectional: true, alignment: AlignmentType.CENTER,
    spacing: { line: LINE, after: 120 },
    children: [run(text, { size, bold })],
  });
}
// simple RTL table
function tbl(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const cell = (t, head) => new TableCell({
    width: { size: 0, type: WidthType.DXA },
    shading: head ? { type: ShadingType.CLEAR, fill: 'E7E6E6', color: 'auto' } : undefined,
    children: [new Paragraph({ bidirectional: true, alignment: AlignmentType.RIGHT, spacing: { line: 276 }, children: [run(t, { bold: head, size: 22 })] })],
  });
  const mk = (r, head) => new TableRow({ children: r.map((t, i) => { const c = cell(t, head); c.options.width = { size: widths[i], type: WidthType.DXA }; return c; }) });
  return new Table({
    visuallyRightToLeft: true,
    width: { size: total, type: WidthType.DXA },
    columnWidths: widths,
    rows: [mk(headers, true), ...rows.map(r => mk(r, false))],
  });
}


// ---- SPSS-look tables (as in the example paper): horizontal rules only, grey header, David 11 ----
const NONE = { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' };
const LINE1 = { style: BorderStyle.SINGLE, size: 4, color: '000000' };
function cellS(text, width, opts = {}) {
  const lines = String(text).split('\n');
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    shading: opts.head ? { type: ShadingType.CLEAR, fill: 'EDEDED', color: 'auto' } : undefined,
    borders: { top: opts.head ? LINE1 : NONE, bottom: opts.head || opts.last ? LINE1 : NONE, left: NONE, right: NONE },
    margins: { top: 50, bottom: 50, left: 70, right: 70 },
    children: lines.map(l => new Paragraph({
      bidirectional: !opts.ltr, alignment: opts.align || (opts.ltr ? AlignmentType.LEFT : AlignmentType.RIGHT),
      spacing: { line: 276, after: 0 },
      children: [new TextRun({ text: l, font: opts.ltr ? { ascii: 'Arial', hAnsi: 'Arial', cs: 'Arial' } : HEB, size: opts.size || 22, bold: !!opts.head || !!opts.bold, rightToLeft: !opts.ltr })],
    })),
  });
}
// RTL table for the body: headers[], rows[][], widths[] (DXA). Numeric cells centred, first column right-aligned.
function tblS(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const mk = (r, head, last) => new TableRow({ tableHeader: head, cantSplit: true, children: r.map((t, i) => cellS(t, widths[i], { head, last, align: (i === 0 ? AlignmentType.RIGHT : AlignmentType.CENTER) })) });
  return new Table({ visuallyRightToLeft: true, width: { size: total, type: WidthType.DXA }, columnWidths: widths,
    borders: { top: LINE1, bottom: LINE1, left: NONE, right: NONE, insideHorizontal: NONE, insideVertical: NONE },
    rows: [mk(headers, true, false), ...rows.map((r, k) => mk(r, false, k === rows.length - 1))] });
}
// LTR table for the SPSS-output appendix (English SPSS labels with Hebrew variable names inside)
function tblL(rows, headerRows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const mk = (r, k) => new TableRow({ tableHeader: k < headerRows, cantSplit: true, children: r.map((t, i) => cellS(t, widths[i], { head: k < headerRows, last: k === rows.length - 1, ltr: true, size: 18, bold: (i === 0 && k >= headerRows), align: (i === 0 ? AlignmentType.LEFT : AlignmentType.CENTER) })) });
  return new Table({ visuallyRightToLeft: false, width: { size: total, type: WidthType.DXA }, columnWidths: widths,
    borders: { top: LINE1, bottom: LINE1, left: NONE, right: NONE, insideHorizontal: NONE, insideVertical: NONE },
    rows: rows.map((r, k) => mk(r, k)) });
}
function CAP(text) { // לוח / תרשים caption, bold, like the example
  return new Paragraph({ bidirectional: true, alignment: AlignmentType.RIGHT, spacing: { before: 200, after: 80, line: LINE }, keepNext: true, children: [run(text, { bold: true })] });
}
function NOTE(text) {
  return new Paragraph({ bidirectional: true, alignment: AlignmentType.JUSTIFIED, spacing: { after: 120, line: 276 }, children: [run(text, { size: 20 })] });
}
function IMG(path, wCm, hCm) {
  return new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120, after: 60 }, keepNext: true,
    children: [new ImageRun({ type: 'png', data: fs.readFileSync(path), transformation: { width: Math.round(wCm * 37.8), height: Math.round(hCm * 37.8) } })] });
}
function PL(text, opts = {}) { // LTR paragraph (English)
  return new Paragraph({ bidirectional: false, alignment: AlignmentType.LEFT, spacing: { line: LINE, after: 120 }, children: [new TextRun({ text, font: { ascii: 'Times New Roman', hAnsi: 'Times New Roman', cs: 'Times New Roman' }, size: opts.size || 24, bold: !!opts.bold, italics: !!opts.italics })] });
}

