// ===== מבוא =====
c.push(H1('מבוא'));
c.push(Pind('היום של תלמיד בישראל מתחלק בין שלוש התנהגויות שכל אחת מהן נחקרה בנפרד במשך שנים: זמן מול מסכים, שעות שינה ופעילות גופנית. בשנים האחרונות התגבשה ההבנה שההתנהגויות האלה אינן נפרדות אלא מתחרות על אותן 24 שעות, ושהאיזון ביניהן קשור לבריאות, לרווחה הנפשית ולתפקוד הלימודי. מחקר בקרב 934 תלמידים בבית ספר אוסטרלי מצא ששני אחוזים בלבד עמדו בשלוש ההמלצות יחד, ושעמידה בהמלצת זמן המסך והקפדה על שעות שינה סדירות בסוף השבוע היו קשורות לציונים גבוהים יותר במתמטיקה ובאנגלית (Howie et al., 2020).'));
c.push(Pind('העבודה הנוכחית מפנה את השאלה הזאת לאוכלוסייה שכמעט אינה מופיעה במחקרים האלה: תלמידים עם לקויות למידה. לקות למידה היא הפרעה נוירו-התפתחותית שמתבטאת בקושי מתמשך ברכישת קריאה, כתיבה או חשבון, והיא מוגדרת בישראל על פי המדריך האבחוני האמריקני (ארן-ארנרייך, 2013; משרד החינוך, ח"ת). לתלמידים אלה יש סיבות להיות פגיעים יותר לחוסר איזון בין מסכים, שינה ותנועה. מחקרים מצביעים על שיעורים גבוהים של הפרעות שינה בקרב ילדים עם דיסלקציה ועם לקות למידה ספציפית (Jeffcock & Dimitriou, 2025; Saccani et al., 2022) ועל קשיים מוטוריים שמלווים את הלקות ומקשים על השתתפות בפעילות גופנית (Blanchet & Assaiante, 2022). בישראל, ניתוח של נתוני הסקר הארצי HBSC הראה שבני נוער עם מוגבלויות הלומדים בחינוך הכללי נבדלים מעמיתיהם בהרגלי הפעילות הגופנית ובמדדי הרווחה (הראל-פיש ואחרים, 2024). עם זאת, כמעט אין מחקר שבדק את שלוש ההתנהגויות יחד בקרב תלמידים עם לקויות למידה, ובוודאי לא בישראל.'));
c.push(Pind('בישראל השאלה דחופה במיוחד. רוב בני הנוער מדווחים על ארבע עד שמונה שעות מסך ביום (איגוד האינטרנט הישראלי, 2022), ומשרד הבריאות פרסם לאחרונה המלצות להורים להגבלת זמן המסך לפי גיל ולהרחקת מסכים מחדרי השינה, בנימוק שהשימוש במסכים בא על חשבון שינה, פעילות גופנית ולמידה (משרד הבריאות, 2026). אם ההמלצות האלה נכונות לכלל התלמידים, יש מקום לבדוק כיצד הן מתקיימות בקרב תלמידים שהלמידה קשה להם ממילא.'));
c.push(Pind('מטרת המחקר היא לתאר את דפוסי החשיפה למסכים, השינה והפעילות הגופנית בקרב תלמידים עם לקויות למידה בחטיבת הביניים ובחטיבה העליונה, לבחון את הקשרים בין שלוש ההתנהגויות לבין התפקוד הלימודי המדווח, ולהשוות את דפוסי ההתנהגות של תלמידים עם לקויות למידה לאלה של תלמידים ללא לקות. המחקר כמותי ומבוסס על שאלון דיווח עצמי אנונימי.'));
c.push(Pind('העבודה בנויה כך: הפרק הראשון סוקר את הספרות. הוא פותח בהגדרת לקויות למידה ובמאפייניהן, ממשיך לשלוש ההתנהגויות הנחקרות ולמודל המשולב של 24 השעות, מציג את תמונת המצב בישראל ומסתיים ברציונל, במטרות, בשאלות ובהשערות המחקר. הפרק השני מתאר את שיטת המחקר: מערך המחקר, אוכלוסיית המחקר, כלי המחקר, ההליך, דרכי ניתוח הנתונים, השיקולים האתיים ומגבלות המחקר. הפרק השלישי מציג את הממצאים לפי סדר שאלות המחקר וההשערות, והפרק הרביעי דן בהם לאור הספרות, מציע מסקנות והמלצות ומסכם. גבולות העבודה: היא עוסקת בתלמידים עם לקות למידה מאובחנת בכיתות ז\' עד י"ב, ואינה עוסקת במוגבלות שכלית, באוטיזם או בלקויות חושיות. הפרעת קשב נדונה רק במידה שהיא נלווית ללקות למידה.'));
