// ===== פרק 1: סקירת ספרות =====
c.push(H1('פרק 1: סקירת הספרות'));

c.push(H2('1.1 לקויות למידה: הגדרה, שכיחות ומאפיינים'));
c.push(Pind('המהדורה החמישית של המדריך האבחוני האמריקני הביאה עמה שינוי מושגי בתחום. במקום המונח "לקות" (Disability) נבחר המונח "הפרעה" (Disorder), ולקות הלמידה הוגדרה כהפרעה נוירו-התפתחותית שבה קשיים ברכישת קריאה, כתיבה או חשבון נמשכים שישה חודשים לפחות למרות התערבות ממוקדת, פוגעים בתפקוד הלימודי או היומיומי, מתחילים בשנות בית הספר ואינם מוסברים על ידי מוגבלות שכלית, ליקוי חושי או חסך בהוראה. ההגדרה עברה מהסתמכות על פער בין אינטליגנציה להישגים אל דרישה לתיעוד של קושי מתמשך שאינו נענה להתערבות. השכיחות בקרב ילדים בגיל בית הספר נאמדת בחמישה עד חמישה עשר אחוזים (American Psychiatric Association, 2013, מצוטט אצל ארן-ארנרייך, 2013).'));
c.push(Pind('בישראל אימץ משרד החינוך את ההגדרה של המדריך האמריקני כבסיס לאבחון ולמתן התאמות, ואגף לקויות למידה והפרעות קשב בשירות הפסיכולוגי-ייעוצי אחראי על גיבוש המדיניות בתחום (משרד החינוך, ח"ת). דוח של מרכז המחקר והמידע של הכנסת סקר את הליכי האיתור והאבחון במערכת החינוך והצביע על פערים בין מגזרים ובין שכבות גיל בזמינות האבחון ובמתן ההתאמות (אבגר, 2018).'));
c.push(Pind('לקות למידה אינה מסתכמת בקושי בקריאה או בחשבון. מחקר ישראלי שהשווה תלמידים עם לקויות למידה לתלמידים ללא לקות מצא שתפקודים ניהוליים וידע עולם תורמים להבנת הנקרא בשתי הקבוצות, ושהפער בתפקודים הניהוליים הוא חלק מהתמונה של הלקות (בשארה ווייס, 2025). תפקודים ניהוליים, ובהם ויסות עצמי ועיכוב תגובה, הם היכולות שנדרשות כדי להפסיק משחק בטלפון וללכת לישון. סקירה שכללה 34 מחקרים משנת 1990 ועד 2022 מצאה שלתלמידים עם לקות למידה ספציפית מיומנויות מוטוריות נמוכות מאלה של בני גילם, ושהפער גדל ככל שהמשימה המוטורית מורכבת יותר וכאשר קיימת תחלואה נלווית. הכותבות קשרו בין הליקויים המוטוריים לבין אורח חיים יושבני (Blanchet & Assaiante, 2022).'));
c.push(Pind('לקות למידה מופיעה לעיתים קרובות יחד עם הפרעת קשב. נייר עמדה של העמותה הישראלית לריפוי בעיסוק מתאר את הפגיעה של הפרעת קשב בהשתתפות בעיסוקי היום-יום, בלמידה ובפנאי, ואת הצורך בהתערבות שמכוונת לשגרות היומיומיות ולא רק לתסמינים (העמותה הישראלית לריפוי בעיסוק, 2017). במצב של תחלואה כפולה של לקות למידה והפרעת קשב מדווחים קשיים בולטים יותר, ובהם הפרעות שינה (Saccani et al., 2022). שלושת המאפיינים האלה, קשיים בוויסות עצמי, קשיים מוטוריים ופגיעות לשינה לקויה, הם הרקע לשאלה של העבודה הנוכחית. הם מרמזים שתלמידים עם לקויות למידה עשויים להתקשות יותר מאחרים לשמור על איזון בין מסכים, שינה ותנועה, ושחוסר איזון כזה עלול להעמיק את הקושי הלימודי.'));

c.push(H2('1.2 חשיפה למסכים בקרב ילדים ובני נוער'));
c.push(Pind('ההמלצה המקובלת בעולם, שאומצה גם במחקר האוסטרלי שעליו נשענת עבודה זו, היא להגביל את זמן המסך לצורכי פנאי לשעתיים ביום לכל היותר (Howie et al., 2020). משרד הבריאות בישראל פרסם בספטמבר 2026 המלצות מדורגות לפי גיל: הימנעות מלאה ממסכים עד גיל שנתיים, עד שעה ביום בגילי שנתיים עד חמש, פחות משעתיים ביום בגילי שש עד תשע, סמארטפון לא לפני גיל 13, רשתות חברתיות לא לפני גיל 15, והרחקת מסכים מחדרי השינה. המשרד נימק את ההמלצות בממצאי סקר HBSC שלפיהם 28.7 אחוזים מתלמידי כיתות ז\' עד י"ב מבלים שש שעות ומעלה מול מסכים מחוץ לשעות הלימודים, ובהשלכות של השימוש על השינה, על הלמידה ועל הבריאות הנפשית (משרד הבריאות, 2026).'));
c.push(Pind('סקר שערך איגוד האינטרנט הישראלי בקיץ 2022 בקרב בני נוער והורים מצא ש-54 אחוזים מבני הנוער בחברה היהודית החילונית מדווחים על ארבע עד שמונה שעות מסך ביום, ו-11 אחוזים נוספים על יותר משמונה שעות. בחברה הערבית השיעור המדווח על ארבע עד שמונה שעות ביום הגיע ל-67 אחוזים, ובחברה היהודית-דתית הוא היה הנמוך ביותר, 41 אחוזים (איגוד האינטרנט הישראלי, 2022). הפער בין ההמלצה של שעתיים לבין הדיווח בפועל הוא פער של פי שניים עד פי ארבעה, ומכאן שהשאלה המחקרית המעניינת אינה אם תלמידים חורגים מההמלצה אלא כמה, ומה זה עושה לשאר היממה שלהם.'));
c.push(Pind('מחקר ישראלי שנערך בקרב 60 תלמידי כיתות ה\' ו-ו\' מיישובי עוטף עזה וממרכז הארץ מדד באותו שאלון את מספר שעות הפעילות הגופנית ואת מספר שעות הצפייה במסכים בשבוע, לצד עמדות כלפי פעילות גופנית וחרדה מצבית. התלמידים דיווחו בממוצע על כ-16 שעות מסך שבועיות לעומת כשמונה שעות של פעילות גופנית, ולא נמצא הבדל בין שתי הקבוצות ובין בנים לבנות. עם זאת, נמצא קשר שלילי בין התפיסה שפעילות גופנית תורמת לבריאות לבין זמן המסך וקשר חיובי בין תפיסה זו לבין זמן הפעילות, כלומר ככל שהילד מייחס לפעילות ערך בריאותי רב יותר, כך זמן המסך שלו קטן וזמן הפעילות שלו גדל (שחף ושלג, 2020). המחקר נערך בכיתות רגילות ולא בדק לקויות למידה, אך הוא מדגים שבקרב ילדים בישראל זמן המסך וזמן הפעילות הגופנית מתחרים זה בזה על שעות הפנאי, ושהם ניתנים למדידה יחד בדיווח עצמי פשוט, כפי שנעשה גם בעבודה הנוכחית.'));
c.push(Pind('בנוגע ללקויות למידה עצמן, המחקר היחיד שנמצא שהשווה ישירות בין קבוצות הוא מחקר טורקי בקרב 86 מתבגרים עם הפרעת קשב ולקות למידה ו-86 מתבגרים עם הפרעת קשב בלבד. המחקר לא מצא הבדל בזמן המסך היומי או בחומרת השימוש הבעייתי, אך מצא שהקבוצה עם לקות הלמידה עסקה במגוון מצומצם יותר של פעילויות מסך והעדיפה פחות משחקי אסטרטגיה ומשחקי חשיבה. המסקנה הייתה שלקות הלמידה מעצבת את אופי השימוש ולא בהכרח את כמותו (Kocabas et al., 2025). מחקר זה כלל רק מתבגרים עם הפרעת קשב, ולכן אינו יכול לומר דבר על תלמידים עם לקות למידה בלבד. הפער הזה בספרות הוא אחת הסיבות למחקר הנוכחי.'));

c.push(H2('1.3 שינה בגיל בית הספר ובקרב תלמידים עם לקויות למידה'));
c.push(Pind('ההמלצות המקובלות הן תשע עד אחת עשרה שעות שינה בלילה לילדים בגילי 5 עד 13 ושמונה עד עשר שעות למתבגרים בגילי 14 עד 17 (Howie et al., 2020). שינה אינה זמן מת. במהלכה המוח מעבד ומגבש את מה שנלמד במשך היום, ושינה חסרה פוגעת בקשב, בזיכרון ובוויסות הרגשי. לכל אדם קצב פנימי משלו שמשתנה עם הגיל, ובגיל ההתבגרות השעון הביולוגי נוטה להתאחר, כך שמתבגרים מתקשים להירדם מוקדם ומתקשים לקום לבית הספר (גספר ואחרים, 2020).'));
c.push(Pind('הקשר בין מדיה אלקטרונית לשינה נחקר רבות. סקירה שיטתית של מחקרים ממדינות מערביות בקרב ילדים עד גיל 15 סיכמה שהשימוש במדיה קשור לשעת שינה מאוחרת יותר, למשך שינה קצר יותר ולפגיעה באיכות השינה, ושהקשר נמצא בסוגי מדיה שונים ובשיטות מדידה שונות (Lund et al., 2021). ההמלצה הישראלית להרחיק מסכים מחדרי השינה נשענת על אותם ממצאים (משרד הבריאות, 2026). במחקר האוסטרלי, משך השינה הכולל לא היה קשור לציונים, אך שעת שינה מאוחרת בסוף השבוע הייתה קשורה לירידה בהישגים, ומכאן שסדירות השינה חשובה לא פחות מכמותה (Howie et al., 2020).'));
c.push(Pind('בקרב ילדים עם לקויות למידה הבעיה בולטת יותר. מחקר איטלקי השווה 74 ילדים עם הפרעת קשב, 78 ילדים עם לקות למידה ספציפית ו-76 ילדים עם שתי האבחנות באמצעות סולם הפרעות השינה לילדים. הקבוצה עם התחלואה הכפולה הציגה הפרעות שינה רבות יותר משתי הקבוצות האחרות, בעיקר קשיים בהירדמות ובשמירה על רצף השינה (Saccani et al., 2022). מחקר קהילתי בבריטניה בקרב הורים ל-160 ילדים בגילי 7 עד 13 עם אבחנה ראשית של דיסלקציה מצא ש-66 אחוזים מהילדים הגיעו לרמה קלינית של הפרעות שינה, בעיקר עיכוב בהירדמות, חרדת שינה וישנוניות בשעות היום. רמות החרדה של הילדים לא היו גבוהות מהרגיל ולא הסבירו את העיכוב בהירדמות, ומכאן שהפרעות השינה בדיסלקציה אינן רק תוצר של מצוקה רגשית (Jeffcock & Dimitriou, 2025). שני המחקרים לא מדדו זמן מסך, ולכן אינם יכולים לומר אם השימוש במסכים תורם לקשיי ההירדמות של ילדים אלה. זה אחד הפערים שהעבודה הנוכחית מבקשת למלא.'));

c.push(H2('1.4 פעילות גופנית ותלמידים עם לקויות למידה'));
c.push(Pind('נייר העמדה של ההסתדרות הרפואית בישראל ממליץ לילדים ולבני נוער על 60 דקות ביום לפחות של פעילות גופנית בעצימות בינונית עד גבוהה, רובה אירובית, בשילוב אימוני כוח מותאמים לגיל שלוש פעמים בשבוע, ומדגיש שאפשר לצבור את הזמן במקטעים לאורך היום (דובנוב-רז ואחרים, 2019). המצב בפועל רחוק מההמלצה. ניתוח של נתוני סקר HBSC בקרב כ-7,000 תלמידי כיתות ו\', ח\' ו-י\' בחינוך הממלכתי, הממלכתי-דתי והממלכתי-ערבי מצא שבנים פעילים גופנית בתדירות גבוהה מבנות, ושגורמים ברמת התלמיד וברמת בית הספר מנבאים יחד את הרגלי הפעילות (בק ואחרים, 2018). מעקב אחר מגמות בין השנים 2010 ל-2018 בקרב תלמידים בגילי 12 עד 18 מצא הבדלים בתדירות ובמשך הפעילות הגופנית לפי סוג הפיקוח, כיתה, מגדר ומעמד חברתי-כלכלי (פחימה ואחרים, 2024). מחקר נוסף על אותו בסיס נתונים הראה שאהבה לשיעורי החינוך הגופני ומשך הפעילות בהם משמשים גורם מגן מפני התנהגויות סיכון בקרב בני נוער, בהבדלים לפי גיל ומגדר (ניסנהולץ-גנות ואחרים, 2021).'));
c.push(Pind('הקשר בין פעילות גופנית להישגים לימודיים בישראל אינו פשוט. מחקר בקרב תלמידי תיכון מצא שבנות העוסקות בספורט הישגי הן בעלות ההישגים הלימודיים הגבוהים ביותר, ואילו בקרב בנים נמצא קשר שלילי בין ספורט הישגי להישגים, ומכאן שהתועלת הלימודית של הפעילות תלויה במגדר ובאופי הפעילות (שחף ואחרים, 2014). ממצא זה מזכיר שאי אפשר להניח מראש שיותר פעילות פירושה יותר הצלחה בלימודים, ושיש למדוד את סוג הפעילות ולא רק את כמותה.'));
c.push(Pind('לתלמידים עם לקויות למידה יש מכשול נוסף בדרך לפעילות גופנית. הסקירה של בלאנשה ואסאיאנטה (Blanchet & Assaiante, 2022) הראתה שקשיים מוטוריים מלווים את הלקות אצל חלק ניכר מהתלמידים, וכי תלמיד שמתקשה בתיאום ובאיזון נוטה להימנע ממשחקי כדור ומספורט תחרותי. ההימנעות מצמצמת את ההתנסות המוטורית, וכך נוצר מעגל של הימנעות ואורח חיים יושבני שמותיר יותר זמן פנוי למסכים. בישראל, מחקר שהשווה בין דירוג הורים לדירוג מורים לחינוך גופני בשאלוני איתור של הפרעה התפתחותית בקואורדינציה מצא הסכמה גבוהה בין השניים, והראה שהמורה לחינוך גופני יכול לשמש גורם מאתר של קשיים מוטוריים בבית הספר (עוגב ויזדי-עוגב, 2024). ניתוח של נתוני HBSC 2018-2019 בקרב כ-13,800 תלמידים בגילי 11 עד 17 השווה בין בני נוער עם מוגבלויות חושיות, פיזיות, קוגניטיביות והתנהגותיות הלומדים בחינוך הכללי לבין עמיתיהם, במדדי פעילות גופנית, התנהגויות סיכון, רווחה נפשית וחוסן (הראל-פיש ואחרים, 2024). זהו המחקר הישראלי הקרוב ביותר לשאלת העבודה הנוכחית, אך הוא איגד סוגי מוגבלות שונים לקבוצה אחת ולא בדק זמן מסך ושינה במקביל.'));

c.push(Pind('פעילות גופנית היא גם כלי התערבות לתלמידים עם לקויות למידה, ולא רק מדד תוצאה. מחקר גישוש ישראלי ליווה שש תלמידות כיתות ג\' עד ו\' עם לקות למידה מאובחנת, שטופלו קודם לכן בשיטות המקובלות של הוראה מתקנת, בתוכנית אימון תנועתי שבועי שנמשכה כחמישה חודשים ושילבה הליכה בתבנית שמינייה עם טכניקות קוגניטיביות-התנהגותיות. בתום התוכנית שיפרו התלמידות באופן מובהק את הישגיהן במבחני הכשרים הקוגניטיביים ובמבחני ההישגים, ובכלל זה בקריאה, ובתי הספר דיווחו על שיפור משמעותי בלמידה. גם בדיקה נוירולוגית של הפעילות החשמלית במוח הצביעה על שינוי (בן-אשר וברגר, 2013). המדגם קטן והמחקר ללא קבוצת ביקורת, אך הוא מדגים שהקשר בין תנועה ללמידה אצל תלמידים אלה ניתן לשינוי. סקירה עדכנית של הספרות על למידה מבוססת תנועה מסכמת שפעילות גופנית קשורה לתפקוד קוגניטיבי ולהישגים לימודיים של ילדים, ושילדים בעלי כושר גופני גבוה מציגים ביצועים קוגניטיביים טובים יותר, ומציעה לשלב תנועה בלמידה העיונית בייחוד לילדים מהחינוך המיוחד (סלפטי ואחרים, 2019).'));
c.push(H2('1.5 המודל המשולב של 24 השעות והקשר לתפקוד הלימודי'));
c.push(Pind('נקודת המוצא התיאורטית של העבודה היא התפיסה שפעילות גופנית, התנהגות יושבנית ושינה מתקיימות באותה יממה, מתחרות זו בזו על הזמן ונוטות להתקבץ יחד, כך ששיפור באחת עשוי לגרור שיפור באחרות. תפיסה זו עומדת בבסיס ההנחיות המשולבות לתנועה במהלך 24 שעות, שעליהן נשען המחקר האוסטרלי (Howie et al., 2020). מכאן שגם מחקר על תלמידים עם לקויות למידה צריך למדוד את שלושתן במקביל.'));
c.push(Pind('המחקר של האווי ואחרים (Howie et al., 2020) הוא הבסיס האמפירי המרכזי לעבודה זו ולכן יתואר בפירוט. המחקר נערך בבית ספר אוסטרלי שבו כל תלמיד מביא מכשיר משלו ללמידה, סביבה שבה המסך הוא כלי לימודי ולא רק בידור. 934 תלמידי כיתות ה\' עד י"ב דיווחו על הרגלי השינה, הפעילות הגופנית וההתנהגות היושבנית שלהם, וההישגים הלימודיים נלקחו מרשומות בית הספר. 74 אחוזים מהתלמידים עמדו בהמלצת השינה, 21 אחוזים בהמלצת הפעילות הגופנית ו-15 אחוזים בלבד בהמלצת זמן המסך. שני אחוזים עמדו בשלוש ההמלצות יחד. תלמידים שעמדו בהמלצת זמן המסך קיבלו בממוצע 5.8 נקודות יותר במדד הלימודי הכללי, 7.9 נקודות יותר במתמטיקה ו-3.8 נקודות יותר באנגלית. שעת שינה מאוחרת בסוף השבוע הייתה קשורה לירידה של 3.4 נקודות במדד הכללי. תלמידים שעמדו בשתי המלצות לפחות, 23 אחוזים מהמדגם, הציגו הישגים גבוהים יותר בכל המקצועות. הכותבים הסיקו שתוכניות התערבות צריכות לפנות לשלוש ההתנהגויות יחד ולא לאחת מהן בלבד (Howie et al., 2020).'));
c.push(Pind('ממצאים דומים התקבלו במדגם גדול בהרבה. בקרב 67,281 ילדים ומתבגרים בסין, עמידה בשלוש ההמלצות הייתה קשורה לסיכוי גבוה יותר להישגים טובים בסינית, במתמטיקה ובאנגלית, ויחסי הסיכויים נעו בין 1.51 ל-1.73. גם כאן, הרכיב שהיה קשור באופן העקבי ביותר להישגים היה העמידה בהמלצת זמן המסך, לבדה או בשילוב עם המלצה אחרת (Chen et al., 2024). סיכום הספרות מעלה תמונה עקבית: זמן מסך, שינה ופעילות גופנית קשורים זה לזה ולתפקוד הלימודי, וההשפעה החזקה ביותר על ההישגים מיוחסת לזמן המסך ולסדירות השינה. הפער הוא שכל המחקרים האלה נערכו באוכלוסייה הכללית. אין בהם קבוצה נפרדת של תלמידים עם לקויות למידה, ואין דרך לדעת אם הקשרים חזקים יותר, חלשים יותר או שונים באופיים אצל תלמידים אלה.'));

c.push(H2('1.6 רציונל המחקר, מטרת המחקר, שאלות המחקר והשערות המחקר'));
c.push(H3('רציונל המחקר'));
c.push(Pind('הספרות מציגה שלושה קווים שאינם נפגשים. הקו הראשון מראה שזמן מסך, שינה ופעילות גופנית קשורים זה לזה ולהישגים הלימודיים באוכלוסייה הכללית (Chen et al., 2024; Howie et al., 2020). הקו השני מראה שתלמידים עם לקויות למידה סובלים משיעורים גבוהים של הפרעות שינה ומקשיים מוטוריים, ושהם עשויים להשתמש במסכים באופן שונה (Blanchet & Assaiante, 2022; Jeffcock & Dimitriou, 2025; Kocabas et al., 2025; Saccani et al., 2022). הקו השלישי מציג את היקף השימוש במסכים ואת שיעורי הפעילות הגופנית הנמוכים בישראל, לצד ההמלצות החדשות (איגוד האינטרנט הישראלי, 2022; בק ואחרים, 2018; משרד הבריאות, 2026; פחימה ואחרים, 2024). המחקר הנוכחי מחבר את שלושת הקווים ובודק את דפוסי שלוש ההתנהגויות, את הקשרים ביניהן ואת הקשר שלהן לתפקוד הלימודי, בקרב תלמידים עם לקויות למידה בישראל.'));
c.push(H3('מטרת המחקר'));
c.push(P('למחקר שלוש מטרות:'));
c.push(NUM('לתאר את היקף החשיפה למסכים, את משך השינה ואיכותה ואת היקף הפעילות הגופנית בקרב תלמידים עם לקויות למידה, ואת שיעור התלמידים העומדים בהמלצות המקובלות.', 'num1'));
c.push(NUM('לבחון את הקשרים בין שלוש ההתנהגויות לבין עצמן ובינן לבין התפקוד הלימודי המדווח.', 'num1'));
c.push(NUM('להשוות בין תלמידים עם לקויות למידה לבין תלמידים ללא לקויות למידה בדפוסי ההתנהגות ובשיעור העמידה בהמלצות.', 'num1'));
c.push(H3('שאלות המחקר'));
c.push(NUM('מהם דפוסי החשיפה למסכים, השינה והפעילות הגופנית בקרב תלמידים עם לקויות למידה, ואיזה שיעור מהם עומד בכל אחת מההמלצות ובשלושתן יחד?', 'num2'));
c.push(NUM('האם קיים קשר בין היקף החשיפה למסכים לבין משך השינה, שעת השינה והישנוניות בשעות היום בקרב תלמידים עם לקויות למידה?', 'num2'));
c.push(NUM('האם קיים קשר בין היקף החשיפה למסכים לבין היקף הפעילות הגופנית בקרב תלמידים עם לקויות למידה?', 'num2'));
c.push(NUM('האם קיים קשר בין החשיפה למסכים, השינה והפעילות הגופנית לבין התפקוד הלימודי המדווח של תלמידים עם לקויות למידה?', 'num2'));
c.push(NUM('האם קיימים הבדלים בין תלמידים עם לקויות למידה לבין תלמידים ללא לקויות למידה בדפוסי ההתנהגות ובשיעור העמידה בהמלצות?', 'num2'));
c.push(H3('השערות המחקר'));
c.push(NUM('יימצא קשר שלילי בין היקף החשיפה למסכים לבין משך השינה, וקשר חיובי בין היקף החשיפה למסכים לבין שעת שינה מאוחרת ובינו לבין ישנוניות בשעות היום (Lund et al., 2021).', 'num3'));
c.push(NUM('יימצא קשר שלילי בין היקף החשיפה למסכים לבין היקף הפעילות הגופנית (Howie et al., 2020).', 'num3'));
c.push(NUM('יימצא קשר שלילי בין היקף החשיפה למסכים לבין התפקוד הלימודי המדווח, וקשר חיובי בין עמידה בהמלצות השינה והפעילות הגופנית לבין התפקוד הלימודי המדווח (Chen et al., 2024; Howie et al., 2020).', 'num3'));
c.push(NUM('תלמידים שעומדים בשתי המלצות לפחות ידווחו על תפקוד לימודי גבוה יותר מתלמידים שעומדים בהמלצה אחת או באף אחת (Howie et al., 2020).', 'num3'));
c.push(NUM('תלמידים עם לקויות למידה ידווחו על משך שינה קצר יותר, על ישנוניות רבה יותר ועל פעילות גופנית מועטה יותר בהשוואה לתלמידים ללא לקויות למידה, ושיעור העומדים בשלוש ההמלצות יחד יהיה נמוך יותר בקרבם (Blanchet & Assaiante, 2022; Jeffcock & Dimitriou, 2025; Saccani et al., 2022).', 'num3'));
c.push(P('לגבי היקף החשיפה למסכים לא מנוסחת השערה מכוונת, מאחר שהמחקר היחיד שהשווה ישירות בין קבוצות לא מצא הבדל בכמות השימוש אלא באופיו (Kocabas et al., 2025). שאלה זו תיבדק כשאלה פתוחה.'));
c.push(BR());

// ===== פרק 2: שיטת המחקר =====
c.push(H1('פרק 2: שיטת המחקר'));
c.push(H2('2.1 מערך המחקר'));
c.push(Pind('המחקר כמותי, במערך רוחבי (חתך) מתאמי-השוואתי. הנתונים נאספו בנקודת זמן אחת באמצעות שאלון דיווח עצמי אנונימי. המערך המתאמי משרת את שאלות המחקר השנייה עד הרביעית, העוסקות בקשרים בין משתנים, והמערך ההשוואתי משרת את השאלה החמישית, העוסקת בהבדלים בין שתי קבוצות. הבחירה במערך רוחבי נובעת ממסגרת הזמן של עבודה סמינריונית ומכך שהמחקר הראשון בתחום באוכלוסייה זו בישראל נועד לתאר ולמפות ולא להוכיח סיבתיות. המערך דומה לזה ששימש במחקר האוסטרלי (Howie et al., 2020) ובמחקרים הישראליים שנשענו על נתוני HBSC (בק ואחרים, 2018; הראל-פיש ואחרים, 2024).'));
c.push(P('משתני המחקר:'));
c.push(BUL('משתנים בלתי תלויים: היקף החשיפה למסכים (שעות ביום בימי חול ובסוף שבוע, ונוכחות מסכים בחדר השינה); משך השינה ושעת השינה; היקף הפעילות הגופנית.'));
c.push(BUL('משתנים תלויים: ישנוניות בשעות היום; תפקוד לימודי מדווח (ממוצע ציונים מדווח ותפקוד יומי בלמידה).'));
c.push(BUL('משתנה קבוצתי: קיום אבחנה של לקות למידה (קבוצת המחקר) לעומת היעדר אבחנה (קבוצת ההשוואה).'));
c.push(BUL('משתני רקע: מין, גיל, כיתה, מגזר, אבחנה נלווית של הפרעת קשב, נטילת טיפול תרופתי.'));

c.push(H2('2.2 אוכלוסיית המחקר והמדגם'));
c.push(Pind('אוכלוסיית המחקר היא תלמידי כיתות ז\' עד י"ב במערכת החינוך בישראל. קבוצת המחקר כוללת תלמידים בעלי אבחון תקף של לקות למידה (אבחון דידקטי או פסיכו-דידקטי) המקבלים התאמות בלמידה או בבחינות. קבוצת ההשוואה כוללת תלמידים מאותן שכבות גיל ללא אבחון של לקות למידה. גודל המדגם המתוכנן היה 120 תלמידים: 60 בקבוצת המחקר ו-60 בקבוצת ההשוואה, בטווח הגילים 12 עד 18. חישוב מקדים באמצעות מחשבון עוצמה סטטיסטית הראה שמדגם של 60 בכל קבוצה מאפשר לזהות הבדל בגודל אפקט בינוני (d = 0.5) בעוצמה של כ-77 אחוזים ברמת מובהקות של 5 אחוזים, ומדגם של 60 בקבוצת המחקר מאפשר לזהות מתאם בינוני (r = 0.35) בעוצמה דומה. בפועל השתתפו במחקר 65 תלמידים, 40 בקבוצת המחקר ו-25 בקבוצת ההשוואה, ומשמעות הפער מהמתוכנן נדונה בפרק המגבלות.'));
c.push(Pind('הדגימה הייתה דגימת נוחות. התלמידים גויסו בשני בתי ספר על-יסודיים שבהם פועל מרכז תמיכה או רכז לקויות למידה, באמצעות פנייה למנהלים וליועצות. קבוצת ההשוואה גויסה מאותם בתי ספר ומאותן שכבות גיל, כדי לצמצם הבדלים סביבתיים בין הקבוצות. קריטריוני ההכללה לקבוצת המחקר היו אבחון לקות למידה שתועד בבית הספר, גיל 12 עד 18 ושליטה בשפת השאלון. קריטריוני אי-ההכללה לשתי הקבוצות היו מוגבלות שכלית, אבחנה של אוטיזם, לקות חושית שאינה מתוקנת או מחלה כרונית שמגבילה פעילות גופנית. תלמידים עם הפרעת קשב נלווית נכללו בקבוצת המחקר, ומשתנה זה נרשם ובוקר בניתוח, בהתאם לממצאים על תחלואה כפולה (Saccani et al., 2022).'));

c.push(H2('2.3 כלי המחקר'));
c.push(Pind('כלי המחקר הוא שאלון סגור לדיווח עצמי שמורכב מחמישה חלקים. השאלון המלא מובא בנספח א\'. משך המילוי היה 15 עד 20 דקות. ככל האפשר נעשה שימוש בפריטים שכבר הועברו לתלמידים בישראל במסגרת סקר HBSC, כדי לאפשר השוואה לנתונים הארציים.'));
c.push(H3('חלק א: שאלון פרטים אישיים'));
c.push(P('שאלון שחובר לצורך המחקר וכולל מין, גיל, כיתה, מגזר, קיום אבחון של לקות למידה וסוגו, קיום אבחנה של הפרעת קשב, ונטילת טיפול תרופתי. השאלון אינו מבקש פרטים מזהים.'));
c.push(H3('חלק ב: שאלון חשיפה למסכים'));
c.push(P('שאלון שחובר לצורך המחקר על בסיס פריטי ההתנהגות היושבנית שבמחקר האוסטרלי (Howie et al., 2020) ופריטי המסכים של סקר HBSC ששימשו במחקרים הישראליים (בק ואחרים, 2018; הראל-פיש ואחרים, 2024). הנבדק מדווח על מספר השעות ביום המוקדשות לכל סוג פעילות מסך בנפרד, בימי חול ובסוף השבוע: צפייה בטלוויזיה ובסרטונים, משחקי מחשב וטלפון, רשתות חברתיות ושיחות, ושימוש במסך לצורכי לימודים. פריטים נוספים בודקים נוכחות של טלפון או מסך אחר בחדר השינה, שימוש במסך בחצי השעה שלפני השינה ומספר ההתעוררויות בלילה בגלל הטלפון, בהתאם להמלצות משרד הבריאות (2026). עמידה בהמלצה מוגדרת כזמן מסך פנאי של עד שעתיים ביום בממוצע (Howie et al., 2020).'));
c.push(H3('חלק ג: שאלון הרגלי שינה וישנוניות'));
c.push(P('החלק כולל שני רכיבים. הרכיב הראשון הוא פריטי הרגלי שינה: שעת השינה ושעת הקימה בימי חול ובסוף השבוע, שמהן מחושבים משך השינה והפער בין ימי חול לסוף השבוע, וזמן ההירדמות (Howie et al., 2020). עמידה בהמלצה מוגדרת כתשע עד אחת עשרה שעות שינה לגיל 13 ומטה ושמונה עד עשר שעות לגיל 14 ומעלה (Howie et al., 2020). הרכיב השני הוא סולם ישנוניות יומית בן שמונה פריטים שחובר לצורך המחקר על בסיס תסמיני הישנוניות היומית הנמדדים בשאלון הרגלי השינה לילדים, ששימש במחקר בקרב ילדים עם דיסלקציה (Jeffcock & Dimitriou, 2025). הפריטים נמדדים בסולם של חמש דרגות מ-0 (אף פעם) עד 4 (תמיד). ציון הסולם הוא סכום הפריטים, בטווח 0 עד 32, וציון גבוה מעיד על ישנוניות רבה יותר. מהימנות הסולם חושבה על נתוני המדגם הנוכחי ומדווחת בפרק הממצאים.'));
c.push(H3('חלק ד: שאלון פעילות גופנית'));
c.push(P('פריטי הפעילות הגופנית של סקר HBSC, כפי שהועברו לתלמידים בישראל (בק ואחרים, 2018; ניסנהולץ-גנות ואחרים, 2021; פחימה ואחרים, 2024): מספר הימים בשבוע האחרון שבהם התלמיד היה פעיל גופנית 60 דקות לפחות, תדירות הפעילות הגופנית הנמרצת מחוץ לשעות הלימודים בשבוע רגיל ומשכה, השתתפות בחוג ספורט או בקבוצה, ומידת הפעילות בשיעורי חינוך גופני. פריט הימים עם 60 דקות משמש להגדרת העמידה בהמלצה של ההסתדרות הרפואית (דובנוב-רז ואחרים, 2019), ופריט סוג הפעילות (הישגית, לא הישגית או ללא פעילות) נלקח מהמחקר הישראלי על ספורט והישגים (שחף ואחרים, 2014).'));
c.push(H3('חלק ה: שאלון תפקוד לימודי מדווח'));
c.push(P('שאלון שחובר לצורך המחקר. הוא כולל דיווח על ממוצע הציונים בתעודה האחרונה ועל הציון האחרון במתמטיקה ובאנגלית, שני המקצועות שנמצאו רגישים ביותר לזמן מסך במחקר האוסטרלי (Howie et al., 2020). בנוסף, חמישה פריטים בסולם של חמש דרגות בודקים תפקוד יומי בלמידה: ריכוז בשיעורים, הכנת שיעורי בית, איחורים, הרגשה של עייפות בשיעורים ותחושת מסוגלות בלמידה. ציון התפקוד היומי הוא ממוצע הפריטים. הדיווח העצמי על ציונים נבחר כדי לשמור על אנונימיות מלאה.'));

c.push(H2('2.4 הליך המחקר'));
c.push(Pind('בשלב הראשון התקבל אישור המרצה המנחה של הסמינריון לנושא המחקר ולשאלת המחקר. לאחר מכן נערכה פנייה למנהלי בתי הספר לקבלת הסכמתם ולזיהוי רכז לקויות הלמידה או היועצת שליוו את איסוף הנתונים. בשלב השני הועברו להורי התלמידים טופסי הסכמה מדעת, שבהם הוסברו נושא המחקר, אופי השאלון, האנונימיות והזכות לסרב או להפסיק בכל שלב. בשלב השלישי הועבר השאלון לתלמידים שהוריהם הסכימו, במסגרת שיעור או שעת חינוך, בנוכחות החוקרת ואיש צוות. השאלון הועבר על גבי טופס מקוון או בדפוס, לפי אפשרויות בית הספר. לתלמידים עם לקויות למידה הוצע להקריא את השאלות בקול או להאריך את זמן המילוי, כדי שהקושי בקריאה לא ישפיע על איכות הדיווח. לפני ההעברה הרחבה נערך מחקר חלוץ בקרב עשרה תלמידים לבדיקת בהירות הניסוח ומשך המילוי, ובעקבותיו תוקן נוסחם של שני פריטים. איסוף הנתונים נמשך כשישה שבועות במהלך סמסטר לימודים רגיל, ולא בתקופת חופשות או בחינות.'));

c.push(H2('2.5 ניתוח הנתונים'));
c.push(Pind('הנתונים נותחו בתוכנת SPSS. תחילה חושבה סטטיסטיקה תיאורית (ממוצעים, סטיות תקן, שכיחויות ואחוזים) לכל משתני המחקר ולשיעור העמידה בכל המלצה ובשלושתן יחד, בנפרד לכל קבוצה. מהימנות הסולמות נבדקה באמצעות אלפא של קרונבך. השערות המחקר הראשונה עד השלישית נבדקו באמצעות מתאמי פירסון בין המשתנים הרציפים, וכאשר ההתפלגות לא הייתה נורמלית באמצעות מתאם ספירמן. ההשערה הרביעית נבדקה באמצעות ניתוח שונות חד-כיווני להשוואת התפקוד הלימודי בין תלמידים העומדים באפס, באחת, בשתיים או בשלוש המלצות. ההשערה החמישית נבדקה באמצעות מבחני t למדגמים בלתי תלויים להשוואת ממוצעים ומבחני חי בריבוע להשוואת שיעורי העמידה בהמלצות בין הקבוצות. לבסוף נערכה רגרסיה לינארית מרובה שבה התפקוד הלימודי המדווח היה המשתנה התלוי, ושלוש ההתנהגויות, לצד משתני הרקע והקבוצה, היו המנבאים, כדי לבחון את התרומה הייחודית של כל התנהגות. רמת המובהקות שאומצה הייתה 5 אחוזים.'));

c.push(H2('2.6 שיקולים אתיים'));
c.push(Pind('המחקר עסק בקטינים מאוכלוסייה רגישה ולכן נדרשה הקפדה יתרה. ההשתתפות הותנתה בהסכמה בכתב של ההורים ובהסכמה של התלמיד עצמו, והתלמיד היה רשאי להפסיק בכל שלב בלי הסבר ובלי שייפגע. השאלון היה אנונימי לחלוטין: לא היו בו שם, מספר זהות או פרט מזהה אחר, והשיוך לקבוצת המחקר נעשה על סמך דיווח עצמי ולא על סמך רשימות של בית הספר. השאלונים המודפסים נשמרים במקום נעול והקבצים המקוונים בקובץ מוגן בסיסמה, והם יושמדו בתום העבודה. במהלך ההעברה הוסברה לתלמידים מטרת המחקר בשפה מותאמת, והודגש שאין תשובות נכונות ולא נכונות. סוגיה ייחודית לאוכלוסייה זו היא הרגישות של תלמידים לסימון כ"מאובחנים" בפני חבריהם. לכן השאלון הועבר לכל תלמידי הכיתה יחד, ללא הפרדה בין הקבוצות, והשיוך נקבע רק בניתוח. המחקר נערך במסגרת עבודה סמינריונית, לאחר קבלת אישור המרצה המנחה לנושא המחקר ולשאלת המחקר ואישור מנהלי בתי הספר.'));

c.push(H2('2.7 מגבלות המחקר'));
c.push(Pind('למחקר כמה מגבלות שיש להביא בחשבון בפירוש הממצאים. המערך רוחבי, ולכן הוא יכול להצביע על קשרים אך לא על כיוון סיבתי. כל המשתנים נמדדו בדיווח עצמי, ודיווח על זמן מסך ועל ציונים חשוף להטיות של זיכרון ושל רצייה חברתית. הדגימה הייתה דגימת נוחות בשני בתי ספר, והמדגם שהתקבל קטן מהמתוכנן, ולכן ההכללה מוגבלת. קבוצת התלמידים עם לקויות למידה אינה אחידה, וסולם הישנוניות חובר לצורך המחקר ולא עבר תיקוף מלא. המגבלות נדונות בהרחבה בסעיף 4.7.'));
