c.push(Pind('מטרת המחקר הייתה לתאר את דפוסי החשיפה למסכים, השינה והפעילות הגופנית בקרב תלמידים עם לקויות למידה, לבחון את הקשרים ביניהם ובינם לבין התפקוד הלימודי, ולהשוות את דפוסי ההתנהגות של תלמידים אלה לאלה של תלמידים ללא לקות. הדיון עוקב אחר סדר ההשערות ומעמת את הממצאים עם הספרות שנסקרה בפרק הראשון.'));

c.push(H2('4.1 המסכים כגורם המרכזי'));
c.push(Pind('הממצא הבולט ביותר של המחקר הוא מקומו של זמן המסך. בקבוצת המחקר הוא היה קשור לכל משתני השינה ולכל מדדי התפקוד הלימודי, ונותר המנבא היחיד המובהק של ממוצע הציונים גם בפיקוח על שינה, ישנוניות ופעילות גופנית. הממצא תואם במדויק את המחקר האוסטרלי שעליו נשענה העבודה, שבו העמידה בהמלצת זמן המסך הייתה ההתנהגות הקשורה ביותר להישגים, ובמיוחד למתמטיקה (Howie et al., 2020), ואת המחקר הסיני הגדול שבו רכיב המסכים היה הקשור באופן העקבי ביותר להישגים (Chen et al., 2024). המחקר הנוכחי מוסיף שהקשר מתקיים גם באוכלוסייה שהתפקוד הלימודי שלה פגיע ממילא, ושגודלו אינו קטן: מתאם של 0.53 עם ממוצע הציונים וירידה של כשעה וחצי נקודות לכל שעת מסך.'));
c.push(Pind('גם הקשר בין מסכים לשינה, שההשערה הראשונה עסקה בו, התקבל בבירור ובכיוון שתיארה הסקירה השיטתית של מחקרים ממדינות מערביות: שעת שינה מאוחרת יותר, שינה קצרה יותר ואיכות שינה ירודה (Lund et al., 2021). הקשר החזק ביותר נמצא עם הישנוניות בשעות היום, ולא עם משך השינה עצמו. ייתכן שההסבר הוא שמשך השינה מדווח בקירוב, ואילו הישנוניות נמדדה בסולם רב-פריטים ומהימן שמשקף את המחיר המצטבר של שינה קצרה, מאוחרת ולא סדירה. ההמלצה הישראלית להרחיק מסכים מחדרי השינה (משרד הבריאות, 2026) מקבלת כאן תמיכה: יותר ממחצית מתלמידי קבוצת המחקר מחזיקים מסך בחדר השינה, וכמעט שלושה רבעים משתמשים בו לפני השינה כמעט תמיד.'));

c.push(H2('4.2 הפעילות הגופנית: היעדר קשר ומשמעותו'));
c.push(Pind('ההשערה השנייה, שזמן מסך רב ילווה בפחות פעילות גופנית, לא אוששה. הממצא מפתיע לנוכח תפיסת התחרות על אותן 24 שעות שעומדת ביסוד ההנחיות המשולבות (Howie et al., 2020), אך יש לו הסבר סביר. הפעילות הגופנית במדגם הייתה נמוכה כמעט אצל כולם: ממוצע של פחות משלושה ימים בשבוע, ותלמיד אחד בלבד מכל קבוצה שעמד בהמלצה של 60 דקות בכל יום (דובנוב-רז ואחרים, 2019). כשהמשתנה כמעט אינו משתנה, קשה למצוא לו מתאמים. תמונה זו עולה בקנה אחד עם הנתונים הארציים על שיעורי הפעילות הנמוכים של תלמידי ישראל ועל הירידה בהם לאורך העשור (בק ואחרים, 2018; פחימה ואחרים, 2024). ייתכן גם שהמסכים דוחקים בעיקר את השינה ואת זמן הלמידה, ולא את הפעילות הגופנית, שכבר קודם לכן הייתה מועטה.'));
c.push(Pind('הפעילות הגופנית גם לא נקשרה באופן מובהק לתפקוד הלימודי, אם כי כיוון הקשר היה חיובי ותרומתה ברגרסיה הייתה השנייה בגודלה אחרי המסכים. ממצא זה מזכיר את המחקר הישראלי שמצא שהקשר בין ספורט להישגים תלוי במגדר ובסוג הפעילות ואינו אחיד (שחף ואחרים, 2014). ייתכן שמדד גס של ימי פעילות אינו לוכד את ההבדל בין פעילות מובנית שתורמת ללמידה (בן-אשר וברגר, 2013) לבין פעילות אקראית. הממצא שתלמידים עם לקויות למידה פעילים פחות מעמיתיהם, גם אם ההבדל לא הגיע למובהקות, תואם את הסקירה שקשרה בין הליקויים המוטוריים של תלמידים אלה לבין הימנעות מפעילות (Blanchet & Assaiante, 2022), ומדגיש את החשיבות של איתור מוקדם של קשיים מוטוריים בבית הספר, למשל באמצעות המורה לחינוך גופני (עוגב ויזדי-עוגב, 2024).'));

c.push(H2('4.3 העמידה בהמלצות'));
c.push(Pind('רק תלמיד אחד מבין 65 עמד בשלוש ההמלצות יחד, ויותר ממחצית לא עמדו באף אחת. השיעורים נמוכים אף מאלה שדווחו באוסטרליה, שם שני אחוזים עמדו בשלושתן ו-74 אחוזים בהמלצת השינה (Howie et al., 2020), ובקבוצת המחקר עמדו בהמלצת השינה 30 אחוזים בלבד. עם זאת, גם במדגם הקטן הזה כל המלצה נוספת לוותה בתפקוד לימודי טוב יותר, בהתאמה למה שנמצא באוסטרליה ובסין (Chen et al., 2024; Howie et al., 2020). המשמעות המעשית היא שאין צורך לחכות לעמידה מלאה בכל ההמלצות: מעבר מאפס המלצות לאחת לווה בפער של יותר מחמש נקודות בממוצע הציונים.'));

c.push(H2('4.4 תלמידים עם וללא לקויות למידה'));
c.push(Pind('ההשוואה בין הקבוצות העלתה שלוש תובנות. ראשית, תלמידים עם לקויות למידה אינם חשופים למסכים יותר מעמיתיהם. הממצא חוזר על מה שנמצא בהשוואה בין מתבגרים עם הפרעת קשב עם ובלי לקות למידה נלווית, שם לא נמצא הבדל בכמות השימוש אלא באופיו (Kocabas et al., 2025). מכאן שהבעיה אינה "יותר מסכים" אלא מה שהמסכים עושים לתלמיד שהלמידה קשה לו ממילא: אותה כמות של מסך נקשרה בקבוצת המחקר לפגיעה גדולה יותר בציונים מאשר בכלל המדגם. שנית, שיעור נמוך משמעותית מתלמידי קבוצת המחקר ישן די הצורך, וההבדלים בישנוניות ובשעת השינה היו בכיוון המשוער בגודל אפקט בינוני. הממצא מתיישב עם השיעורים הגבוהים של הפרעות שינה שדווחו בקרב ילדים עם לקות למידה ספציפית ועם דיסלקציה (Jeffcock & Dimitriou, 2025; Saccani et al., 2022). בניגוד למחקר האיטלקי, שמצא את הקשיים הבולטים ביותר בקרב ילדים עם תחלואה כפולה של לקות למידה והפרעת קשב, במחקר הנוכחי לא נמצאו הבדלים בין תלמידים עם וללא הפרעת קשב בתוך קבוצת המחקר. ייתכן שהסיבה היא הטיפול התרופתי שכמחצית מהם נוטלים, וכן גודל המדגם. שלישית, הפער בתפקוד הלימודי בין הקבוצות היה גדול, אך החידוש הוא שבתוך קבוצת המחקר זמן המסך והישנוניות הסבירו חלק ניכר מהשונות בציונים. משמע, לא כל הפער בין תלמיד עם לקות למידה לבין עמיתיו נגזר מהלקות עצמה, וחלק ממנו קשור להרגלים שניתן לשנות. הקשר בין תפקודים ניהוליים לבין הבנת הנקרא שנמצא אצל תלמידים עם לקויות למידה בישראל (בשארה ווייס, 2025) מציע מנגנון אפשרי: הקושי בוויסות עצמי מקשה על התלמיד לסגור את המסך וללכת לישון, והשינה החסרה פוגעת שוב באותם תפקודים ניהוליים שהלמידה נשענת עליהם.'));

c.push(H2('4.5 מסקנות'));
c.push(Pind('ארבע מסקנות עולות מהממצאים. הראשונה, בקרב תלמידים עם לקויות למידה זמן המסך הוא הגורם ההתנהגותי הקשור באופן החזק ביותר לשינה ולתפקוד הלימודי, ותרומתו נותרת גם בפיקוח על יתר ההתנהגויות. השנייה, שינה חסרה ולא סדירה שכיחה יותר בקרב תלמידים אלה מאשר בקרב עמיתיהם, והיא קשורה לישנוניות בשעות היום ולציונים נמוכים יותר. השלישית, הפעילות הגופנית נמוכה בשתי הקבוצות עד כדי כך שאינה מסבירה הבדלים, ולכן היא יעד להתערבות ולא רק משתנה למדידה. הרביעית, העמידה בהמלצות מתגמלת באופן מדורג, וגם המלצה אחת שמתקיימת מלווה בתפקוד טוב יותר.'));

c.push(H2('4.6 תרומת המחקר והשלכות יישומיות'));
c.push(Pind('תרומת המחקר היא בהבאת המודל של שלוש ההתנהגויות, שנחקר עד כה באוכלוסייה הכללית, אל תלמידים עם לקויות למידה בישראל, ובמדידת שלוש ההתנהגויות יחד באותו מדגם. מהממצאים נגזרות כמה המלצות מעשיות. ברמת בית הספר, מומלץ שמרכז התמיכה או רכז לקויות הלמידה יכלול בתוכנית העבודה עם כל תלמיד מאובחן שיחה קצרה על הרגלי מסך ושינה, בדומה לשיחה על התאמות בבחינות, ויציע כלים פשוטים: שעת סיום קבועה למסכים, טעינת הטלפון מחוץ לחדר השינה ושמירה על שעת השינה גם בסוף השבוע. עוד מומלץ שהמורה לחינוך גופני יקבל את רשימת התלמידים עם לקויות למידה ויעקוב אחר השתתפותם בשיעורים, בהתאם לתפקידו כגורם מאתר של קשיים מוטוריים (עוגב ויזדי-עוגב, 2024), ושבית הספר יציע להם פעילות תנועתית מובנית בקבוצה קטנה, כפי שנוסה בהצלחה בישראל (בן-אשר וברגר, 2013). ברמת ההורים, ההמלצה החשובה ביותר היא להוציא את המסכים מחדר השינה ולהפסיק את השימוש בהם חצי שעה לפני השינה, בהתאם להמלצות משרד הבריאות (2026), ולשמור על שעת שינה קבועה בסוף השבוע. ברמת המדיניות, ראוי שההמלצות הארציות בנושא מסכים ושינה יתייחסו במפורש לתלמידים עם לקויות למידה, שכן אצלם המחיר של אותה כמות מסך גבוה יותר. דוגמה למודל התערבות אפשרי היא תוכנית חברו"ת, תוכנית חונכות מקוונת שבה סטודנטים לחינוך גופני ליוו בני נוער בסיכון בפעילות גופנית ובקשר אישי במשך כחצי שנה בתקופת הקורונה. בקרב המשתתפים נמצאה לאחריה עלייה בחוסן ובתמיכה החברתית וירידה במצוקה הפסיכולוגית, ואילו בקבוצת הביקורת לא נמצא שינוי (גלסר ואחרים, 2022). מודל דומה, שמשלב פעילות גופנית עם ליווי אישי, עשוי להתאים גם לתלמידים עם לקויות למידה, שאצלם ההימנעות מפעילות קשורה לא פעם לחוויית כישלון ולא לחוסר עניין.'));

c.push(H2('4.7 הערכה ביקורתית ומגבלות המחקר'));
c.push(Pind('הערכה ביקורתית של המחקר מעלה שתי נקודות שכותב העבודה רואה כחשובות במיוחד. הראשונה נוגעת למדידה: זמן המסך נמדד כסכום שעות, ואילו הממצא של קוקבש ואחרים (Kocabas et al., 2025) מרמז שאצל תלמידים עם לקויות למידה השאלה החשובה היא מה עושים מול המסך ולא רק כמה. ייתכן שחלק מהקשר שנמצא עם הציונים משקף שימוש פסיבי ומאוחר בלילה, ולא כל שימוש, ומדד כולל מטשטש זאת. השנייה נוגעת לכיוון ההשפעה: הפרשנות שהמסכים פוגעים בשינה ובלמידה טבעית ומתיישבת עם הספרות, אך תלמיד שנכשל בלמידה ומתקשה להירדם עשוי לברוח אל המסך, ואז המסך הוא סימפטום ולא סיבה. המחקר הנוכחי אינו יכול להכריע בין שני ההסברים, והתובנה המעשית שלו תקפה בשניהם: הרגלי המסך והשינה הם נקודת כניסה נגישה להתערבות, גם אם אינם המקור היחיד לקושי.'));
c.push(Pind('למחקר כמה מגבלות שמחייבות זהירות בפירוש. המדגם קטן מהמתוכנן, 65 תלמידים במקום 120, ובמיוחד קבוצת ההשוואה, ולכן חלק מההבדלים בין הקבוצות, שגודל האפקט שלהם בינוני, לא הגיעו למובהקות. המערך רוחבי ואינו מאפשר לקבוע כיוון סיבתי: ייתכן שתלמידים שמתקשים להירדם פונים למסך, ולא רק להפך. כל המשתנים נמדדו בדיווח עצמי, כולל הציונים, וסולם התפקוד היומי הציג מהימנות בינונית בלבד. קבוצת המחקר אינה אחידה וכוללת סוגי לקות שונים ותלמידים עם ובלי הפרעת קשב, והמדגם לא איפשר ניתוח נפרד לכל תת-קבוצה. הדגימה היא דגימת נוחות במספר קטן של בתי ספר, ולכן ההכללה מוגבלת.'));

c.push(H2('4.8 כיווני מחקר עתידיים'));
c.push(Pind('מחקר המשך צריך לכלול מדגם גדול יותר עם קבוצת השוואה בגודל דומה לקבוצת המחקר, כדי לבדוק אם ההבדלים בשינה ובפעילות הגופנית שנמצאו כאן בכיוון המשוער יתגלו כמובהקים. מערך אורך, שבו זמן המסך והשינה נמדדים בתחילת השנה והציונים בסופה, יאפשר להתקרב למסקנה סיבתית. מדידה אובייקטיבית של זמן המסך באמצעות דוחות השימוש של הטלפון ושל השינה באמצעות מד תאוצה תפחית את הטיות הדיווח העצמי. ראוי גם לבדוק את אופי השימוש במסך ולא רק את כמותו, בעקבות הממצא שלקות הלמידה מעצבת את סוג הפעילות (Kocabas et al., 2025), ולבחון בניסוי מבוקר אם תוכנית פעילות גופנית מובנית לתלמידים עם לקויות למידה משפרת את השינה ואת התפקוד הלימודי, כהמשך למחקר הגישוש הישראלי (בן-אשר וברגר, 2013).'));

// ===== סיכום =====
c.push(H2('4.9 סיכום'));
c.push(Pind('העבודה יצאה מהשאלה כיצד מתחלקות 24 השעות של תלמיד עם לקות למידה בין מסכים, שינה ותנועה, ומה הקשר בין החלוקה הזאת לבין תפקודו בלימודים. הספרות הראתה שבאוכלוסייה הכללית שלוש ההתנהגויות קשורות זו לזו ולהישגים, אך לא נמצא מחקר שבדק את שלושתן יחד בקרב תלמידים עם לקויות למידה בישראל. המחקר הנוכחי, מחקר כמותי בקרב 40 תלמידים עם לקויות למידה ו-25 תלמידים ללא לקות בכיתות ז\' עד י"ב, מצא שזמן המסך הוא הגורם הקשור באופן החזק ביותר לשינה קצרה ומאוחרת, לישנוניות ולציונים נמוכים, שתלמידים עם לקויות למידה ישנים די הצורך בשיעור נמוך משמעותית מעמיתיהם, שהפעילות הגופנית נמוכה בשתי הקבוצות, ושכל המלצה שמתקיימת מלווה בתפקוד לימודי טוב יותר. המסקנה המעשית פשוטה: לצד ההתאמות בבחינות, שיחה על שעת כיבוי המסכים והוצאת הטלפון מחדר השינה היא התערבות זולה שעשויה לתרום לתלמיד עם לקות למידה לא פחות. הצעד הבא הוא מחקר גדול יותר, במערך אורך ובמדידה אובייקטיבית, שיבדוק אם שינוי ההרגלים אכן משנה את התוצאות.'));
